 482:     /// file, or its size no longer matches the manifest (contract v7,
 483:     /// SOURCE_SIDE_CONTAINMENT D-A/D-C) — a SKIP record in its place.
 484:     /// Nothing of a skipped file is announced on the wire.
 485:     pub async fn send_file(
 486:         &mut self,
 487:         source: Arc<dyn TransferSource>,
 488:         header: &FileHeader,
 489:     ) -> Result<FileSendOutcome> {
 490:         let rel = &header.relative_path;
 491:         let mut file = match source.open_file(header).await {
 492:             Ok(file) => file,
 493:             Err(err) => {
 494:                 let reason = format!("source: cannot open: {err:#}");
 495:                 self.send_skip(rel, &reason).await?;
 496:                 return Ok(FileSendOutcome::Skipped(reason));
 497:             }
 498:         };
 499:         let now = file
 500:             .len()
 501:             .await
 502:             .with_context(|| format!("reading the size of {rel}"))?;
 503:         if now != header.size {
 504:             let reason = format!(
 505:                 "source: changed size during transfer (manifest {} bytes, now {now})",
 506:                 header.size
 507:             );
 508:             self.send_skip(rel, &reason).await?;
 509:             return Ok(FileSendOutcome::Skipped(reason));
 510:         }
 511:         self.send_file_from_reader(header, &mut file).await?;
 512:         Ok(FileSendOutcome::Sent)
 513:     }
