  35:             Self::Auxiliary(task) => SourceScanJoin::Auxiliary(task.join_mut().await),
  36:         }
  37:     }
  38: 
  39:     async fn abort_and_join(&mut self) {
  40:         match self {
  41:             Self::Count { task, .. } => {
  42:                 let _ = task.abort_and_join_mut().await;
  43:             }
  44:             Self::Auxiliary(task) => {
  45:                 let _ = task.abort_and_join_mut().await;
  46:             }
  47:         }
  48:     }
