  62: impl SourceScan {
  63:     pub fn new(primary: tokio::task::JoinHandle<Result<u64>>) -> Self {
  64:         Self {
  65:             tasks: vec![SourceScanTask::Count {
  66:                 task: AbortOnDrop::new(primary),
  67:                 reported: true,
  68:             }],
  69:         }
  70:     }
  71: 
  72:     pub fn add_auxiliary(&mut self, task: tokio::task::JoinHandle<()>) {
  73:         self.tasks
  74:             .push(SourceScanTask::Auxiliary(AbortOnDrop::new(task)));
  75:     }
  76: 
  77:     /// Replace the reported count producer while retaining the prior scan as
  78:     /// an owned child whose failure and lifetime remain part of this run.
  79:     pub fn replace_primary(&mut self, primary: tokio::task::JoinHandle<Result<u64>>) {
  80:         for task in &mut self.tasks {
  81:             if let SourceScanTask::Count { reported, .. } = task {
  82:                 *reported = false;
  83:             }
  84:         }
  85:         self.tasks.push(SourceScanTask::Count {
  86:             task: AbortOnDrop::new(primary),
  87:             reported: true,
  88:         });
  89:     }
