  91:     pub async fn finish(&mut self) -> Result<u64> {
  92:         let reported_index = self
  93:             .tasks
  94:             .iter()
  95:             .position(SourceScanTask::is_reported_count)
  96:             .expect("SourceScan::finish called once");
  97:         let reported = self.tasks[reported_index].join().await;
  98:         self.tasks.remove(reported_index);
  99:         let count = match reported {
 100:             SourceScanJoin::Count(Ok(Ok(count))) => count,
 101:             SourceScanJoin::Count(Ok(Err(error))) => {
 102:                 self.abort_and_join().await;
 103:                 return Err(error);
 104:             }
 105:             SourceScanJoin::Count(Err(error)) => {
 106:                 self.abort_and_join().await;
