 112:         while !self.tasks.is_empty() {
 113:             let joined = self
 114:                 .tasks
 115:                 .last_mut()
 116:                 .expect("non-empty manifest task stack")
 117:                 .join()
 118:                 .await;
 119:             self.tasks.pop();
 120:             match joined {
 121:                 SourceScanJoin::Count(Ok(Ok(_))) | SourceScanJoin::Auxiliary(Ok(())) => {}
 122:                 SourceScanJoin::Count(Ok(Err(error))) => {
 123:                     self.abort_and_join().await;
 124:                     return Err(error);
 125:                 }
 126:                 SourceScanJoin::Count(Err(error)) => {
 127:                     self.abort_and_join().await;
 128:                     return Err(eyre::eyre!("manifest scan task panicked: {error}"));
 129:                 }
 130:                 SourceScanJoin::Auxiliary(Err(error)) => {
 131:                     self.abort_and_join().await;
 132:                     return Err(eyre::eyre!("manifest helper panicked: {error}"));
 133:                 }
 134:             }
 135:         }
 136:         Ok(count)
 137:     }
