  49: fn write_tree(root: &Path, files: &[(&str, Vec<u8>, i64)]) {
  50:     for (rel, content, mtime) in files {
  51:         let path = root.join(rel);
  52:         if let Some(parent) = path.parent() {
  53:             std::fs::create_dir_all(parent).unwrap();
  54:         }
  55:         std::fs::write(&path, content).unwrap();
  56:         filetime::set_file_mtime(&path, filetime::FileTime::from_unix_time(*mtime, 0)).unwrap();
  57:     }
  58: }
  59: 
  60: fn collect_tree(root: &Path) -> BTreeMap<String, Vec<u8>> {
  61:     fn walk(root: &Path, dir: &Path, out: &mut BTreeMap<String, Vec<u8>>) {
  62:         for entry in std::fs::read_dir(dir).unwrap() {
  63:             let path = entry.unwrap().path();
  64:             if path.is_dir() {
  65:                 walk(root, &path, out);
  66:             } else {
  67:                 let rel = path
  68:                     .strip_prefix(root)
  69:                     .unwrap()
  70:                     .to_string_lossy()
  71:                     .replace('\\', "/");
  72:                 out.insert(rel, std::fs::read(&path).unwrap());
  73:             }
  74:         }
  75:     }
  76:     let mut out = BTreeMap::new();
  77:     if root.exists() {
  78:         walk(root, root, &mut out);
  79:     }
  80:     out
  81: }
