 155: /// Drive one session src→dst with `source` (the fault-injecting one)
 156: /// under the given initiator role and carrier.
 157: async fn run_with(
 158:     open: SessionOpen,
 159:     carrier: Carrier,
 160:     source: Arc<dyn TransferSource>,
 161:     dst_root: PathBuf,
 162: ) -> (
 163:     eyre::Result<TransferSummary>,
 164:     eyre::Result<DestinationOutcome>,
 165: ) {
 166:     let initiator_role = TransferRole::try_from(open.initiator_role).unwrap();
 167:     let loopback = || (carrier == Carrier::DataPlane).then(|| "127.0.0.1".to_string());
 168:     let (source_endpoint, dest_endpoint, source_host, dest_host) = match initiator_role {
 169:         TransferRole::Source => (
 170:             SessionEndpoint::initiator(open),
 171:             SessionEndpoint::Responder,
 172:             loopback(),
 173:             None,
 174:         ),
 175:         TransferRole::Destination => (
 176:             SessionEndpoint::Responder,
 177:             SessionEndpoint::initiator(open),
 178:             None,
 179:             loopback(),
 180:         ),
 181:         TransferRole::Unspecified => unreachable!(),
 182:     };
 183:     let source_cfg = SourceSessionConfig {
 184:         instruments: Default::default(),
 185:         hello: HelloConfig::default(),
 186:         endpoint: source_endpoint,
 187:         plan_options: PlanOptions::default(),
 188:         data_plane_host: source_host,
 189:     };
 190:     let dest_cfg = DestinationSessionConfig {
 191:         hello: HelloConfig::default(),
 192:         endpoint: dest_endpoint,
 193:         data_plane_host: dest_host,
 194:         receiver_capacity: None,
 195:         instruments: Default::default(),
 196:         local_apply: None,
 197:     };
 198:     let (a, b) = in_process_pair();
 199:     tokio::time::timeout(SUITE_TIMEOUT, async {
 200:         tokio::join!(
 201:             run_source(source_cfg, a, source),
 202:             run_destination(dest_cfg, b, DestinationTarget::Fixed(dst_root)),
 203:         )
 204:     })
 205:     .await
 206:     .expect("session run timed out")
 207: }
